import heapq

def wall_clock(durations, workers):
    if not durations:
        return 0
    free_at = [0] * workers
    heapq.heapify(free_at)
    end = 0
    for d in durations:
        start = heapq.heappop(free_at)
        finish = start + d
        end = max(end, finish)
        heapq.heappush(free_at, finish)
    return end

def speedup(durations, workers):
    return round(sum(durations) / wall_clock(durations, workers), 2)
